<script setup lang="ts">
import { onMounted, ref, watch } from "vue";
import AppBreadcrumb from "@/components/AppBreadcrumb.vue";
import PageHeader from "@/components/PageHeader.vue";
import { ApiError } from "@/services/http";
import { createSolicitud, getSolicitudOptions, listSolicitudes, updateSolicitud, type Solicitud, type SolicitudOptions, type SolicitudPayload } from "@/services/solicitudes";

const items = ref<Solicitud[]>([]); const options = ref<SolicitudOptions>({ beneficiarios: [], tiposSolicitud: [], tiposVigencia: [], estadosSolicitud: [], periodos: [] }); const search = ref(""); const page = ref(1); const pagination = ref({ page: 1, pageSize: 10, total: 0, totalPages: 0 }); const loading = ref(false); const saving = ref(false); const error = ref(""); const formError = ref(""); const success = ref(""); const editing = ref<Solicitud | null>(null); const showForm = ref(false);
const form = ref({ codigoSolicitud: "", idBeneficiario: 0, idPeriodoAcademico: null as number | null, idTipoSolicitud: null as number | null, idTipoVigencia: 0, idEstadoSolicitud: 0, fechaInicioSolicitada: "", fechaFinSolicitada: "", motivoSolicitud: "", origenSolicitud: "" });
const message = (value: unknown) => value instanceof ApiError ? value.message : "Ocurrió un error inesperado";
async function load() { loading.value = true; error.value = ""; try { const result = await listSolicitudes(search.value, page.value); items.value = result.items; pagination.value = result.pagination; } catch (cause) { error.value = message(cause); } finally { loading.value = false; } }
async function loadOptions() { try { options.value = await getSolicitudOptions(); } catch (cause) { error.value = message(cause); } }
function edit(item: Solicitud | null) { editing.value = item; formError.value = ""; form.value = { codigoSolicitud: item?.codigoSolicitud ?? "", idBeneficiario: item?.idBeneficiario ?? 0, idPeriodoAcademico: item?.idPeriodoAcademico ?? null, idTipoSolicitud: item?.idTipoSolicitud ?? null, idTipoVigencia: item?.idTipoVigencia ?? 0, idEstadoSolicitud: item?.idEstadoSolicitud ?? 0, fechaInicioSolicitada: item?.fechaInicioSolicitada?.slice(0, 10) ?? "", fechaFinSolicitada: item?.fechaFinSolicitada?.slice(0, 10) ?? "", motivoSolicitud: item?.motivoSolicitud ?? "", origenSolicitud: item?.origenSolicitud ?? "" }; showForm.value = true; }
function payload(): SolicitudPayload { return { codigoSolicitud: form.value.codigoSolicitud, idBeneficiario: form.value.idBeneficiario, idPeriodoAcademico: form.value.idPeriodoAcademico, idTipoSolicitud: form.value.idTipoSolicitud, idTipoVigencia: form.value.idTipoVigencia, idEstadoSolicitud: form.value.idEstadoSolicitud, fechaInicioSolicitada: form.value.fechaInicioSolicitada ? new Date(`${form.value.fechaInicioSolicitada}T00:00:00`) : null, fechaFinSolicitada: form.value.fechaFinSolicitada ? new Date(`${form.value.fechaFinSolicitada}T00:00:00`) : null, motivoSolicitud: form.value.motivoSolicitud || null, origenSolicitud: form.value.origenSolicitud }; }
async function save() { formError.value = ""; saving.value = true; try { if (editing.value) await updateSolicitud(editing.value.idSolicitud, payload()); else await createSolicitud(payload()); showForm.value = false; success.value = editing.value ? "Solicitud actualizada correctamente." : "Solicitud creada correctamente."; await load(); } catch (cause) { formError.value = message(cause); } finally { saving.value = false; } }
function changePage(nextPage: number) { page.value = nextPage; void load(); } watch(search, () => { page.value = 1; void load(); }); onMounted(() => { void Promise.all([load(), loadOptions()]); });
</script>

<template>
  <AppBreadcrumb :items="[{ label: 'Administración', to: '/' }, { label: 'Operación' }, { label: 'Solicitudes' }]" />
  <PageHeader eyebrow="Operación" title="Solicitudes" description="Gestión de solicitudes de acceso vinculadas a beneficiarios reales." action-label="Nueva solicitud" @action="edit(null)" />
  <div v-if="success" class="bo-notice bo-notice-success">{{ success }}</div><div v-if="error" class="bo-state bo-state-error">{{ error }} <button class="bo-link" @click="load">Reintentar</button></div>
  <section class="bo-card"><form class="bo-toolbar" @submit.prevent="load"><input v-model="search" placeholder="Buscar por código, beneficiario o cuenta..." aria-label="Buscar solicitudes" /><button class="bo-btn bo-btn-primary">Filtrar</button></form><div v-if="loading" class="bo-state">Cargando solicitudes...</div><div v-else-if="!items.length" class="bo-state"><strong>No hay solicitudes registradas.</strong><span>Ajuste la búsqueda o cree una nueva solicitud.</span></div><div v-else class="bo-table-wrap"><table><thead><tr><th>Código</th><th>Beneficiario</th><th>Tipo</th><th>Fecha</th><th>Vigencia</th><th>Estado</th><th>Acciones</th></tr></thead><tbody><tr v-for="item in items" :key="item.idSolicitud"><td><strong>{{ item.codigoSolicitud }}</strong></td><td>{{ item.nombreBeneficiario }}<small>{{ item.numeroCuenta ?? "Sin cuenta" }}</small></td><td>{{ item.nombreTipoSolicitud ?? "-" }}</td><td>{{ new Date(item.fechaSolicitud).toLocaleDateString("es-HN") }}</td><td>{{ item.nombreTipoVigencia }}</td><td><span class="status-badge" :class="{ 'status-badge--inactive': !item.estadoSolicitud }">{{ item.nombreEstadoSolicitud }}</span></td><td><button class="bo-action" @click="edit(item)">Editar</button></td></tr></tbody></table></div><footer v-if="!loading" class="bo-pagination"><span>{{ pagination.total }} registros · Página {{ pagination.page }} de {{ Math.max(pagination.totalPages, 1) }}</span><div><button class="bo-page-button" :disabled="page <= 1" @click="changePage(page - 1)">Anterior</button><button class="bo-page-button" :disabled="page >= pagination.totalPages" @click="changePage(page + 1)">Siguiente</button></div></footer></section>
  <div v-if="showForm" class="bo-modal-backdrop" @click.self="showForm = false"><section class="bo-modal"><header><div><span class="bo-eyebrow">{{ editing ? "Editar registro" : "Nuevo registro" }}</span><h2>{{ editing ? "Editar solicitud" : "Crear solicitud" }}</h2></div><button class="bo-close" type="button" @click="showForm = false">×</button></header><form class="bo-form" @submit.prevent="save"><div class="bo-form-grid"><label>Código de solicitud *<input v-model="form.codigoSolicitud" maxlength="30" required /></label><label>Beneficiario *<select v-model.number="form.idBeneficiario" required><option :value="0" disabled>Seleccione...</option><option v-for="item in options.beneficiarios" :key="item.idBeneficiario" :value="item.idBeneficiario">{{ item.nombreBeneficiario }} · {{ item.numeroCuenta ?? "Sin cuenta" }}</option></select></label><label>Tipo de solicitud<select v-model="form.idTipoSolicitud"><option :value="null">Sin tipo</option><option v-for="item in options.tiposSolicitud" :key="item.idTipoSolicitud" :value="item.idTipoSolicitud">{{ item.nombreTipoSolicitud }}</option></select></label><label>Período académico<select v-model="form.idPeriodoAcademico"><option :value="null">Sin período</option><option v-for="item in options.periodos" :key="item.idPeriodoAcademico" :value="item.idPeriodoAcademico">{{ item.codigoPeriodoAcademico }} · {{ item.nombrePeriodoAcademico }}</option></select></label><label>Tipo de vigencia *<select v-model.number="form.idTipoVigencia" required><option :value="0" disabled>Seleccione...</option><option v-for="item in options.tiposVigencia" :key="item.idTipoValor" :value="item.idTipoValor">{{ item.nombreTipoValor }}</option></select></label><label>Estado *<select v-model.number="form.idEstadoSolicitud" required><option :value="0" disabled>Seleccione...</option><option v-for="item in options.estadosSolicitud" :key="item.idTipoValor" :value="item.idTipoValor">{{ item.nombreTipoValor }}</option></select></label><label>Inicio solicitado<input v-model="form.fechaInicioSolicitada" type="date" /></label><label>Fin solicitado<input v-model="form.fechaFinSolicitada" type="date" /></label><label>Origen *<input v-model="form.origenSolicitud" maxlength="30" required /></label><label class="bo-form-wide">Motivo<textarea v-model="form.motivoSolicitud" maxlength="1500" rows="3" /></label></div><p v-if="formError" class="bo-form-error">{{ formError }}</p><footer><button class="bo-btn" type="button" @click="showForm = false">Cancelar</button><button class="bo-btn bo-btn-primary" :disabled="saving">{{ saving ? "Guardando..." : "Guardar" }}</button></footer></form></section></div>
</template>
